void tick_screen_settings() {
}

typedef void (*tick_screen_func_t)();
tick_screen_func_t tick_screen_funcs[] = {
    tick_screen_main,
    tick_screen_waiting,
    tick_screen_finished,
    tick_screen_gps_stale,
    tick_screen_missing_data,
    tick_screen_overtime,
    tick_screen_plan_demo,
    tick_screen_cached_plan,
    tick_screen_expired_plan,
    tick_screen_lap_corrected,
    tick_screen_settings,
};
void tick_screen(int screen_index) {
    if (screen_index >= 0 && screen_index < 11) {
        tick_screen_funcs[screen_index]();
    }
}
void tick_screen_by_id(enum ScreensEnum screenId) {
    tick_screen(screenId - 1);
}

