uint32_t active_theme_index = 0;

//
//
//

void create_screens() {

// Set default LVGL theme
    lv_display_t *dispp = lv_display_get_default();
    lv_theme_t *theme = lv_theme_default_init(dispp, lv_palette_main(LV_PALETTE_BLUE), lv_palette_main(LV_PALETTE_RED), false, LV_FONT_DEFAULT);
    lv_display_set_theme(dispp, theme);
    
    // Initialize screens
    // Create screens
    create_screen_main();
    create_screen_waiting();
    create_screen_finished();
    create_screen_gps_stale();
    create_screen_missing_data();
    create_screen_overtime();
    create_screen_plan_demo();
    create_screen_cached_plan();
    create_screen_expired_plan();
    create_screen_lap_corrected();
    create_screen_settings();
}